				<el-form-item class="upload" v-else-if="ruleForm.juanzengzhaopian" label="捐赠照片" prop="juanzengzhaopian" >
					<img v-if="ruleForm.juanzengzhaopian.substring(0,4)=='http'&&ruleForm.juanzengzhaopian.split(',w').length>1" class="upload-img" style="margin-right:20px;" v-bind:key="index" :src="ruleForm.juanzengzhaopian" width="100" height="100">
					<img v-else-if="ruleForm.juanzengzhaopian.substring(0,4)=='http'" class="upload-img" style="margin-right:20px;" v-bind:key="index" :src="ruleForm.juanzengzhaopian.split(',')[0]" width="100" height="100">
					<img v-else class="upload-img" style="margin-right:20px;" v-bind:key="index" v-for="(item,index) in ruleForm.juanzengzhaopian.split(',')" :src="$base.url+item" width="100" height="100">
				</el-form-item>
				<el-form-item class="input" v-if="type!='info'"  label="受助者账号" prop="shouzhuzhezhanghao" >
					<el-input v-model="ruleForm.shouzhuzhezhanghao" placeholder="受助者账号" clearable  :readonly="ro.shouzhuzhezhanghao"></el-input>
				</el-form-item>
				<el-form-item v-else class="input" label="受助者账号" prop="shouzhuzhezhanghao" >
					<el-input v-model="ruleForm.shouzhuzhezhanghao" placeholder="受助者账号" readonly></el-input>
				</el-form-item>
				<el-form-item class="input" v-if="type!='info'"  label="受助者姓名" prop="shouzhuzhexingming" >
					<el-input v-model="ruleForm.shouzhuzhexingming" placeholder="受助者姓名" clearable  :readonly="ro.shouzhuzhexingming"></el-input>
				</el-form-item>
				<el-form-item v-else class="input" label="受助者姓名" prop="shouzhuzhexingming" >
					<el-input v-model="ruleForm.shouzhuzhexingming" placeholder="受助者姓名" readonly></el-input>
				</el-form-item>
				<el-form-item class="input" v-if="type!='info'"  label="捐赠列表" prop="juanzengliebiao" >
					<el-input v-model="ruleForm.juanzengliebiao" placeholder="捐赠列表" clearable  :readonly="ro.juanzengliebiao"></el-input>
				</el-form-item>
				<el-form-item v-else class="input" label="捐赠列表" prop="juanzengliebiao" >
					<el-input v-model="ruleForm.juanzengliebiao" placeholder="捐赠列表" readonly></el-input>
				</el-form-item>
				<el-form-item class="date" v-if="type!='info'" label="捐赠时间" prop="juanzengshijian" >
					<el-date-picker
						value-format="yyyy-MM-dd HH:mm:ss"
						v-model="ruleForm.juanzengshijian" 
						type="datetime"
						:readonly="ro.juanzengshijian"
						placeholder="捐赠时间"
					></el-date-picker>
				</el-form-item>
				<el-form-item class="input" v-else-if="ruleForm.juanzengshijian" label="捐赠时间" prop="juanzengshijian" >
					<el-input v-model="ruleForm.juanzengshijian" placeholder="捐赠时间" readonly></el-input>
				</el-form-item>
				<el-form-item class="input" v-if="type!='info'"  label="备注" prop="beizhu" >
					<el-input v-model="ruleForm.beizhu" placeholder="备注" clearable  :readonly="ro.beizhu"></el-input>
				</el-form-item>
				<el-form-item v-else class="input" label="备注" prop="beizhu" >
					<el-input v-model="ruleForm.beizhu" placeholder="备注" readonly></el-input>
				</el-form-item>
				<el-form-item class="select" v-if="type!='info'"  label="捐赠状态" prop="juanzengzhuangtai" >
					<el-select :disabled="ro.juanzengzhuangtai" v-model="ruleForm.juanzengzhuangtai" placeholder="请选择捐赠状态" >
						<el-option
							v-for="(item,index) in juanzengzhuangtaiOptions"
							v-bind:key="index"
							:label="item"
							:value="item">
						</el-option>
					</el-select>
				</el-form-item>
				<el-form-item v-else class="input" label="捐赠状态" prop="juanzengzhuangtai" >
					<el-input v-model="ruleForm.juanzengzhuangtai"
						placeholder="捐赠状态" readonly></el-input>
				</el-form-item>
			</template>
			<el-form-item class="btn">
				<el-button class="btn3"  v-if="type!='info'" type="success" @click="onSubmit">
					<span class="icon iconfont icon-xihuan"></span>
					提交
				</el-button>
				<el-button class="btn4" v-if="type!='info'" type="success" @click="back()">
					<span class="icon iconfont icon-xihuan"></span>
					取消
				</el-button>
				<el-button class="btn5" v-if="type=='info'" type="success" @click="back()">
					<span class="icon iconfont icon-xihuan"></span>
					返回
				</el-button>
			</el-form-item>
		</el-form>
    

	</div>
</template>
<script>
	export default {
		data() {
			return {
				id: '',
				type: '',
			
			
				ro:{
					juanzengbianhao : false,
					suoxuwuzi : false,
					shouhuodizhi : false,
					juanzengzhezhanghao : false,
					juanzengzhexingming : false,
					juanzengzhaopian : false,
					shouzhuzhezhanghao : false,
					shouzhuzhexingming : false,
					juanzengliebiao : false,
					juanzengshijian : false,
					beizhu : false,
					juanzengzhuangtai : false,
					sfsh : false,
					shhf : false,
				},
			
				ruleForm: {
					juanzengbianhao: this.getUUID(),
					suoxuwuzi: '',
					shouhuodizhi: '',
					juanzengzhezhanghao: '',
					juanzengzhexingming: '',
					juanzengzhaopian: '',
					shouzhuzhezhanghao: '',
					shouzhuzhexingming: '',
					juanzengliebiao: '',
					juanzengshijian: '',
					beizhu: '',
					juanzengzhuangtai: '已提交',
					shhf: '',
				},
				juanzengzhuangtaiOptions: [],

				rules: {
					juanzengbianhao: [
					],
					suoxuwuzi: [
					],
					shouhuodizhi: [
					],
					juanzengzhezhanghao: [
					],
					juanzengzhexingming: [
					],
					juanzengzhaopian: [
					],
					shouzhuzhezhanghao: [
					],
					shouzhuzhexingming: [
					],
					juanzengliebiao: [
					],
					juanzengshijian: [
					],
					beizhu: [
					],
					juanzengzhuangtai: [
					],
					sfsh: [
					],
					shhf: [
					],
				},
			};
		},
		props: ["parent"],
		computed: {



		},
		components: {
		},
		created() {
			this.ruleForm.juanzengshijian = this.getCurDateTime()
		},
		methods: {
			// 下载
			download(file){
				window.open(`${file}`)
			},
			// 初始化
			init(id,type) {
				if (id) {
					this.id = id;
					this.type = type;
				}
				if(this.type=='info'||this.type=='else'||this.type=='msg'){
					this.info(id);
				}else if(this.type=='logistics'){
					for(let x in this.ro) {
						this.ro[x] = true
					}
					this.logistics=false;
					this.info(id);
				}else if(this.type=='cross'){
					var obj = this.$storage.getObj('crossObj');
					for (var o in obj){
						if(o=='juanzengbianhao'){
							this.ruleForm.juanzengbianhao = obj[o];
							this.ro.juanzengbianhao = true;
							continue;
						}
						if(o=='suoxuwuzi'){
							this.ruleForm.suoxuwuzi = obj[o];
							this.ro.suoxuwuzi = true;
							continue;
						}
						if(o=='shouhuodizhi'){
							this.ruleForm.shouhuodizhi = obj[o];
							this.ro.shouhuodizhi = true;
							continue;
						}
						if(o=='juanzengzhezhanghao'){
							this.ruleForm.juanzengzhezhanghao = obj[o];
							this.ro.juanzengzhezhanghao = true;
							continue;
						}
						if(o=='juanzengzhexingming'){
							this.ruleForm.juanzengzhexingming = obj[o];
							this.ro.juanzengzhexingming = true;
							continue;
						}
						if(o=='juanzengzhaopian'){
							this.ruleForm.juanzengzhaopian = obj[o];
							this.ro.juanzengzhaopian = true;
							continue;
						}
						if(o=='shouzhuzhezhanghao'){
							this.ruleForm.shouzhuzhezhanghao = obj[o];
							this.ro.shouzhuzhezhanghao = true;
							continue;
						}
						if(o=='shouzhuzhexingming'){
							this.ruleForm.shouzhuzhexingming = obj[o];
							this.ro.shouzhuzhexingming = true;
							continue;
						}
						if(o=='juanzengliebiao'){
							this.ruleForm.juanzengliebiao = obj[o];
							this.ro.juanzengliebiao = true;
							continue;
						}
						if(o=='juanzengshijian'){
							this.ruleForm.juanzengshijian = obj[o];
							this.ro.juanzengshijian = true;
							continue;
						}
						if(o=='beizhu'){
							this.ruleForm.beizhu = obj[o];
							this.ro.beizhu = true;
							continue;
						}
						if(o=='juanzengzhuangtai'){
							this.ruleForm.juanzengzhuangtai = obj[o];
							this.ro.juanzengzhuangtai = true;
							continue;
						}
					}
					this.ruleForm.juanzengzhuangtai = '已提交'; 				}
				// 获取用户信息
				this.$http({
					url: `${this.$storage.get('sessionTable')}/session`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						var json = data.data;
						if(((json.juanzengzhezhanghao!=''&&json.juanzengzhezhanghao) || json.juanzengzhezhanghao==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.juanzengzhezhanghao = json.juanzengzhezhanghao
							this.ro.juanzengzhezhanghao = true;
						}
						if(((json.juanzengzhexingming!=''&&json.juanzengzhexingming) || json.juanzengzhexingming==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.juanzengzhexingming = json.juanzengzhexingming
							this.ro.juanzengzhexingming = true;
						}
					} else {
						this.$message.error(data.msg);
					}
				});
				this.juanzengzhuangtaiOptions = "已接收,审核中".split(',')
			
			},
			// 多级联动参数

			info(id) {
				this.$http({
					url: `juanzengjilu/info/${id}`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						this.ruleForm = data.data;
						//解决前台上传图片后台不显示的问题
						let reg=new RegExp('../../../upload','g')//g代表全部
					} else {
						this.$message.error(data.msg);
					}
				});
			},

			// 提交
			async onSubmit() {
					if(this.ruleForm.juanzengbianhao) {
						this.ruleForm.juanzengbianhao = String(this.ruleForm.juanzengbianhao)
					}
					if(this.ruleForm.juanzengzhaopian!=null) {
						this.ruleForm.juanzengzhaopian = this.ruleForm.juanzengzhaopian.replace(new RegExp(this.$base.url,"g"),"");
					}
					var objcross = this.$storage.getObj('crossObj');
					if(!this.ruleForm.id) {
						delete this.ruleForm.userid
					}
					await this.$refs["ruleForm"].validate(async valid => {
						if (valid) {
							if(this.type=='cross'){
								var statusColumnName = this.$storage.get('statusColumnName');
								var statusColumnValue = this.$storage.get('statusColumnValue');
								if(statusColumnName!='') {
									var obj = this.$storage.getObj('crossObj');
									if(statusColumnName && !statusColumnName.startsWith("[")) {
										for (var o in obj){
											if(o==statusColumnName){
												obj[o] = statusColumnValue;
											}
										}
										var table = this.$storage.get('crossTable');
										await this.$http({
											url: `${table}/update`,
											method: "post",
											data: obj
										}).then(({ data }) => {});
									}
								}
							}
							
							await this.$http({
								url: `juanzengjilu/${!this.ruleForm.id ? "save" : "update"}`,
								method: "post",
								data: this.ruleForm
							}).then(async ({ data }) => {
								if (data && data.code === 0) {
									this.$message({
										message: "操作成功",
										type: "success",
										duration: 1500,
										onClose: () => {
											this.parent.showFlag = true;
											this.parent.addOrUpdateFlag = false;
											this.parent.juanzengjiluCrossAddOrUpdateFlag = false;
											this.parent.search();
											this.parent.contentStyleChange();
										}
									});
								} else {
									this.$message.error(data.msg);
								}
							});
						}
					});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.parent.showFlag = true;
				this.parent.addOrUpdateFlag = false;
				this.parent.juanzengjiluCrossAddOrUpdateFlag = false;
				this.parent.contentStyleChange();
			},
			juanzengzhaopianUploadChange(fileUrls) {
				this.ruleForm.juanzengzhaopian = fileUrls;
			},
		}
	};
</script>
