<script>
	export default {
		data() {
			return {
				id: '',
				type: '',
			
			
				ro:{
					juanzengbianhao : false,
					shouzhuzhezhanghao : false,
					shouzhuzhexingming : false,
					touxiang : false,
					juanzengzhezhanghao : false,
					juanzengzhexingming : false,
					shoudaowupinqingdan : false,
					ganxiang : false,
					pingjia : false,
					fabushijian : false,
				},
			
				ruleForm: {
					juanzengbianhao: '',
					shouzhuzhezhanghao: '',
					shouzhuzhexingming: '',
					touxiang: '',
					juanzengzhezhanghao: '',
					juanzengzhexingming: '',
					shoudaowupinqingdan: '',
					ganxiang: '',
					pingjia: '',
					fabushijian: '',
				},

				rules: {
					juanzengbianhao: [
					],
					shouzhuzhezhanghao: [
					],
					shouzhuzhexingming: [
					],
					touxiang: [
					],
					juanzengzhezhanghao: [
					],
					juanzengzhexingming: [
					],
					shoudaowupinqingdan: [
					],
					ganxiang: [
					],
					pingjia: [
					],
					fabushijian: [
					],
				},
			};
		},
		props: ["parent"],
		computed: {



		},
		components: {
		},
		created() {
			this.ruleForm.fabushijian = this.getCurDateTime()
		},
		methods: {
			// 下载
			download(file){
				window.open(`${file}`)
			},
			// 初始化
			init(id,type) {
				if (id) {
					this.id = id;
					this.type = type;
				}
				if(this.type=='info'||this.type=='else'||this.type=='msg'){
					this.info(id);
				}else if(this.type=='logistics'){
					for(let x in this.ro) {
						this.ro[x] = true
					}
					this.logistics=false;
					this.info(id);
				}else if(this.type=='cross'){
					var obj = this.$storage.getObj('crossObj');
					for (var o in obj){
						if(o=='juanzengbianhao'){
							this.ruleForm.juanzengbianhao = obj[o];
							this.ro.juanzengbianhao = true;
							continue;
						}
						if(o=='shouzhuzhezhanghao'){
							this.ruleForm.shouzhuzhezhanghao = obj[o];
							this.ro.shouzhuzhezhanghao = true;
							continue;
						}
						if(o=='shouzhuzhexingming'){
							this.ruleForm.shouzhuzhexingming = obj[o];
							this.ro.shouzhuzhexingming = true;
							continue;
						}
						if(o=='touxiang'){
							this.ruleForm.touxiang = obj[o];
							this.ro.touxiang = true;
							continue;
						}
						if(o=='juanzengzhezhanghao'){
							this.ruleForm.juanzengzhezhanghao = obj[o];
							this.ro.juanzengzhezhanghao = true;
							continue;
						}
						if(o=='juanzengzhexingming'){
							this.ruleForm.juanzengzhexingming = obj[o];
							this.ro.juanzengzhexingming = true;
							continue;
						}
						if(o=='shoudaowupinqingdan'){
							this.ruleForm.shoudaowupinqingdan = obj[o];
							this.ro.shoudaowupinqingdan = true;
							continue;
						}
						if(o=='ganxiang'){
							this.ruleForm.ganxiang = obj[o];
							this.ro.ganxiang = true;
							continue;
						}
						if(o=='pingjia'){
							this.ruleForm.pingjia = obj[o];
							this.ro.pingjia = true;
							continue;
						}
						if(o=='fabushijian'){
							this.ruleForm.fabushijian = obj[o];
							this.ro.fabushijian = true;
							continue;
						}
					}
				}
				// 获取用户信息
				this.$http({
					url: `${this.$storage.get('sessionTable')}/session`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						var json = data.data;
						if(((json.shouzhuzhezhanghao!=''&&json.shouzhuzhezhanghao) || json.shouzhuzhezhanghao==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.shouzhuzhezhanghao = json.shouzhuzhezhanghao
							this.ro.shouzhuzhezhanghao = true;
						}
						if(((json.shouzhuzhexingming!=''&&json.shouzhuzhexingming) || json.shouzhuzhexingming==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.shouzhuzhexingming = json.shouzhuzhexingming
							this.ro.shouzhuzhexingming = true;
						}
						if(((json.touxiang!=''&&json.touxiang) || json.touxiang==0) && this.$storage.get("role")!="管理员"){
							this.ruleForm.touxiang = json.touxiang
							this.ro.touxiang = true;
						}
					} else {
						this.$message.error(data.msg);
					}
				});
			
			},
			// 多级联动参数

			info(id) {
				this.$http({
					url: `fankuijuanzeng/info/${id}`,
					method: "get"
				}).then(({ data }) => {
					if (data && data.code === 0) {
						this.ruleForm = data.data;
						//解决前台上传图片后台不显示的问题
						let reg=new RegExp('../../../upload','g')//g代表全部
					} else {
						this.$message.error(data.msg);
					}
				});
			},

			// 提交
			async onSubmit() {
					if(this.ruleForm.touxiang!=null) {
						this.ruleForm.touxiang = this.ruleForm.touxiang.replace(new RegExp(this.$base.url,"g"),"");
					}
					var objcross = this.$storage.getObj('crossObj');
					if(!this.ruleForm.id) {
						delete this.ruleForm.userid
					}
					await this.$refs["ruleForm"].validate(async valid => {
						if (valid) {
							if(this.type=='cross'){
								var statusColumnName = this.$storage.get('statusColumnName');
								var statusColumnValue = this.$storage.get('statusColumnValue');
								if(statusColumnName!='') {
									var obj = this.$storage.getObj('crossObj');
									if(statusColumnName && !statusColumnName.startsWith("[")) {
										for (var o in obj){
											if(o==statusColumnName){
												obj[o] = statusColumnValue;
											}
										}
										var table = this.$storage.get('crossTable');
										await this.$http({
											url: `${table}/update`,
											method: "post",
											data: obj
										}).then(({ data }) => {});
									}
								}
							}
							
							await this.$http({
								url: `fankuijuanzeng/${!this.ruleForm.id ? "save" : "update"}`,
								method: "post",
								data: this.ruleForm
							}).then(async ({ data }) => {
								if (data && data.code === 0) {
									this.$message({
										message: "操作成功",
										type: "success",
										duration: 1500,
										onClose: () => {
											this.parent.showFlag = true;
											this.parent.addOrUpdateFlag = false;
											this.parent.fankuijuanzengCrossAddOrUpdateFlag = false;
											this.parent.search();
											this.parent.contentStyleChange();
										}
									});
								} else {
									this.$message.error(data.msg);
								}
							});
						}
					});
			},
			// 获取uuid
			getUUID () {
				return new Date().getTime();
			},
			// 返回
			back() {
				this.parent.showFlag = true;
				this.parent.addOrUpdateFlag = false;
				this.parent.fankuijuanzengCrossAddOrUpdateFlag = false;
				this.parent.contentStyleChange();
			},
			touxiangUploadChange(fileUrls) {
				this.ruleForm.touxiang = fileUrls;
			},
		}
	};
</script>
